def as_list(v):
    if v is None: return []
    return v if isinstance(v,list) else [v]

def get(d,*keys):
    if not isinstance(d,dict): return None
    by={norm(k):v for k,v in d.items()}
    for k in keys:
        if norm(k) in by: return by[norm(k)]
    return None

def country(record):
    explicit=get(record,'Pais','País','Country','pais')
    n=norm(explicit)
    if 'elsalvador' in n or n in ('sv','salvador'): return 'El Salvador'
    if 'guatemala' in n or n=='gt': return 'Guatemala'
    text=' '.join(str(get(record,k) or '') for k in ('Banco','Cuenta','Moneda','archivo','hoja','Descripcion','Dirección','Direccion','Pais'))
    n=norm(text)
    if 'elsalvador' in n or 'salvador' in n or 'elsalvadoreno' in n or 'sv' in n: return 'El Salvador'
    if 'guatemala' in n or 'guatemalteco' in n or 'gt' in n: return 'Guatemala'
    currency=norm(get(record,'Moneda','moneda'))
    if currency in ('usd','us dollar','dolares','dollar'): return 'El Salvador'
    if currency in ('gtq','quetzal','quetzales','q'): return 'Guatemala'
    return None

